const BASE_URL = process.env.REACT_APP_API_URL
console.log("URL:" + BASE_URL)

export class LocaisService {

    static getAll() {
        return fetch(`${BASE_URL}/api/local/all`,
        {
                method: "GET",
                headers: {
                    "Content-Type": "application/json",
                }
            }
        )
    }

    static async create(payload) {

        return fetch(`${BASE_URL}/api/local`,
        {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
                body: JSON.stringify(payload),
            }
        )
    }

    static async update(id, payload) {

    }

    static delete(id) {
        return fetch(`${BASE_URL}/api/local/${encodeURIComponent(id)}`, {
            method: "DELETE",
            headers: {
                "Content-Type": "application/json",
            },
        });
    }

    static getTags(localId) {
        return fetch(`${BASE_URL}/api/local/${encodeURIComponent(localId)}/tags`, {
            method: "GET",
            headers: {
                "Content-Type": "application/json",
            },
        });
    }

    static associateTag(localId, tagId) {
        return fetch(
            `${BASE_URL}/api/local/${encodeURIComponent(localId)}/tag/${encodeURIComponent(tagId)}`,
            {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
            }
        );
    }
}
